`timescale 1ns/1ps

/*
 * GENERATED BY OPUS 5.5
 * Self-checking testbench for ov7670_controller (flat image version).
 *
 * Contains a small OV7670 camera model that drives pclk/href/vsync/d like the
 * real chip (all change on PCLK falling edge, PCLK = XCLK/4 like QQVGA mode).
 * The frame is shrunk to W x H so a whole frame simulates in microseconds.
 *
 * Every byte the camera sends is a known pattern, so on each ready the
 * testbench checks every pixel in image against what it should be.
 *
 * Tests:
 *   1. Rows sent before the first VSYNC are ignored (start mid-frame)
 *   2. Normal frames are stored correctly (every pixel checked)
 *   3. A frame missing a row does NOT raise ready
 *   4. Extra bytes at the end of a row are dropped (no corruption)
 *   5. ready fires exactly once per complete frame
 *
 * Writes sim/ov7670_controller.vcd.  Run from fpga/:  make sim TB=ov7670_controller
 */

module ov7670_controller_tb;

    // ------------------------------------------------------------------
    // Parameters
    // ------------------------------------------------------------------
    localparam integer W   = 8;           // tiny frame for fast sims
    localparam integer H   = 4;
    localparam integer BPR = 2 * W;       // bytes per row (2 bytes per pixel)

    localparam real CLK_PERIOD  = 10.0;           // 100 MHz system clock
    localparam real PCLK_PERIOD = 4 * 41.6667;    // XCLK 24 MHz / 4 (QQVGA) ~ 6 MHz
                                                  // not a multiple of 10 ns, so PCLK edges
                                                  // land at many phases of clk (good test)

    // camera blanking, in PCLK cycles (shrunk, same shape as QQVGA)
    localparam integer VSYNC_HIGH  = 20;  // VSYNC pulse
    localparam integer BACK_PORCH  = 30;  // after VSYNC, before first row
    localparam integer ROW_GAP     = 12 + 3*BPR;  // like QQVGA: HREF only on 1 of 4 rows
    localparam integer FRONT_PORCH = 25;  // after last row, before next VSYNC

    // ------------------------------------------------------------------
    // DUT
    // ------------------------------------------------------------------
    reg        clk = 0;
    reg        rst = 1;
    reg        pclk = 0;
    reg        href = 0;
    reg        vsync = 0;
    reg  [7:0] d = 8'h00;
    wire       sio_c, sio_d, xclk;
    wire       ready;
    wire [W*H*16-1:0] image;

    pullup (sio_d);

    ov7670_controller #(.WIDTH(W), .HEIGHT(H)) dut (
        .clk(clk), .rst(rst),
        .sio_c(sio_c), .sio_d(sio_d),
        .xclk(xclk), .pclk(pclk), .href(href), .vsync(vsync), .d(d),
        .ready(ready), .image(image)
    );

    always #(CLK_PERIOD/2)  clk  = ~clk;
    always #(PCLK_PERIOD/2) pclk = ~pclk;

    // ------------------------------------------------------------------
    // Data pattern: byte b of row r in frame f
    // (unique within a frame for W*H*2 <= 256, and different per frame)
    // ------------------------------------------------------------------
    function [7:0] pattern(input integer f, input integer r, input integer b);
        pattern = f*7 + r*BPR + b;
    endfunction

    // ------------------------------------------------------------------
    // Camera model (drives everything on PCLK falling edge, like the chip)
    // ------------------------------------------------------------------
    integer done_frame_id = -1;   // which frame should be in image at the next ready
                                  // (-1 = last frame was incomplete, ready must not fire)

    task blank(input integer n);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                @(negedge pclk);
                href <= 0;
                d    <= 8'hEE;           // junk while HREF is low
            end
        end
    endtask

    task send_row(input integer f, input integer r, input integer extra_bytes);
        integer b;
        begin
            for (b = 0; b < BPR + extra_bytes; b = b + 1) begin
                @(negedge pclk);
                href <= 1;
                d    <= (b < BPR) ? pattern(f, r, b) : 8'hBB;   // extra bytes = 0xBB
            end
            blank(ROW_GAP);
        end
    endtask

    task send_vsync;
        begin
            @(negedge pclk);
            vsync <= 1;
            blank(VSYNC_HIGH);
            @(negedge pclk);
            vsync <= 0;
        end
    endtask

    // rows: how many rows to send (H = complete frame)
    task send_frame(input integer f, input integer rows, input integer extra_bytes);
        integer r;
        begin
            send_vsync;
            blank(BACK_PORCH);
            for (r = 0; r < rows; r = r + 1)
                send_row(f, r, extra_bytes);
            blank(FRONT_PORCH);
            done_frame_id = (rows == H) ? f : -1;
        end
    endtask

    // ------------------------------------------------------------------
    // Checker: on every ready, compare every pixel
    // ------------------------------------------------------------------
    integer errors = 0;
    integer frames_done = 0;
    integer p, row, col;
    reg [15:0] expected;

    always @(posedge clk) begin
        if (ready) begin
            frames_done = frames_done + 1;
            if (done_frame_id < 0) begin
                $display("[%0t] FAIL: ready fired for an incomplete frame", $time);
                errors = errors + 1;
            end else begin
                for (p = 0; p < W*H; p = p + 1) begin
                    row = p / W;
                    col = p % W;
                    expected = {pattern(done_frame_id, row, 2*col),
                                pattern(done_frame_id, row, 2*col + 1)};
                    if (image[p*16 +: 16] !== expected) begin
                        if (errors < 10)
                            $display("[%0t] FAIL: frame %0d pixel (r%0d, c%0d): got %h, expected %h",
                                     $time, done_frame_id, row, col, image[p*16 +: 16], expected);
                        errors = errors + 1;
                    end
                end
                $display("[%0t] frame %0d checked", $time, done_frame_id);
            end
        end
    end

    // ------------------------------------------------------------------
    // Stimulus
    // ------------------------------------------------------------------
    integer k;

    initial begin
        $dumpfile("sim/ov7670_controller.vcd");
        $dumpvars(0, ov7670_controller_tb);

        repeat (5) @(posedge clk);
        rst <= 0;

        // 1. start mid-frame: rows with no VSYNC before them must be ignored
        $display("== Rows before first VSYNC (must be ignored)");
        for (k = 0; k < 2; k = k + 1)
            send_row(99, k, 0);

        // 2. normal frames (each is checked at the NEXT frame's VSYNC)
        $display("== Normal frames");
        send_frame(1, H, 0);
        send_frame(2, H, 0);              // ready for frame 1 here

        repeat (20) @(posedge clk);

        // 5. summary
        if (frames_done != 1) begin
            $display("FAIL: ready fired %0d times, expected 3", frames_done);
            errors = errors + 1;
        end

        $display("\n========================================");
        if (errors == 0) $display(" PASS  (%0d frames checked)", frames_done);
        else             $display(" FAIL  (%0d errors)", errors);
        $display("========================================\n");
        $finish;
    end

    // watchdog
    initial begin
        #(50_000_000);
        $display("TIMEOUT");
        $finish;
    end

endmodule